import{_ as i,a as n}from"./chunks/ENU-NED.C1XIYZk4.js";import{_ as s,C as l,c as h,o as d,j as a,G as o,a as r,al as p}from"./chunks/framework.CT7RwC5a.js";const v=JSON.parse('{"title":"Neural Networks","description":"","frontmatter":{},"headers":[],"relativePath":"zh/advanced/neural_networks.md","filePath":"zh/advanced/neural_networks.md"}'),u={name:"zh/advanced/neural_networks.md"};function c(m,e,f,k,g,w){const t=l("Badge");return d(),h("div",null,[e[0]||(e[0]=a("h1",{id:"neural-networks",tabindex:"-1"},[r("Neural Networks "),a("a",{class:"header-anchor",href:"#neural-networks","aria-label":'Permalink to "Neural Networks"'},"​")],-1)),o(t,{type:"tip",text:"main (planned for: PX4 v1.17)"}),e[1]||(e[1]=r()),o(t,{type:"warning",text:"Experimental"}),e[2]||(e[2]=p(`<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is an experimental module. Use at your own risk.</p></div><p>The Multicopter Neural Network (NN) module (<a href="./../modules/modules_controller.html#mc_nn_control">mc_nn_control</a>) is an example module that allows you to experiment with using a pre-trained neural network on PX4. It might be used, for example, to experiment with controllers for non-traditional drone morphologies, computer vision tasks, and so on.</p><p>The module integrates a pre-trained neural network based on the <a href="./../advanced/tflm.html">TensorFlow Lite Micro (TFLM)</a> module. The module is trained for the <a href="./../frames_multicopter/holybro_x500v2_pixhawk6c.html">X500 V2</a> multicopter frame. While the controller is fairly robust, and might work on other platforms, we recommend <a href="#training-your-own-network">Training your own Network</a> if you use a different vehicle. Note that after training the network you will need to update and rebuild PX4.</p><p>TLFM is a mature inference library intended for use on embedded devices. It has support for several architectures, so there is a high likelihood that you can build it for the board you want to use. If not, there are other possible NN frameworks, such as <a href="https://eigen.tuxfamily.org/index.php?title=Main_Page" target="_blank" rel="noreferrer">Eigen</a> and <a href="https://pytorch.org/executorch-overview" target="_blank" rel="noreferrer">Executorch</a>.</p><p>This document explains how you can include the module in your PX4 build, and provides a broad overview of how it works. The other documents in the section provide more information about the integration, allowing you to replace the NN with a version trained on different data, or even to replace the TLFM library altogether.</p><p>If you are looking for more resources to learn about the module, a website has been created with links to a youtube video and a workshop paper. A full master&#39;s thesis will be added later. <a href="https://ntnu-arl.github.io/px4-nns/" target="_blank" rel="noreferrer">A Neural Network Mode for PX4 on Embedded Flight Controllers</a>.</p><h2 id="neural-network-px4-firmware" tabindex="-1">Neural Network PX4 Firmware <a class="header-anchor" href="#neural-network-px4-firmware" aria-label="Permalink to &quot;Neural Network PX4 Firmware&quot;">​</a></h2><p>The module has been tested on a number of configurations, which can be build locally using the commands:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_neural</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6c_neural</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mro_pixracerpro_neural</span></span></code></pre></div><p>You can add the module to other board configurations by modifying their <code>default.px4board file</code> configuration to include these lines:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_LIB_TFLM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_MODULES_MC_NN_CONTROL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <code>mc_nn_control</code> module takes up roughly 50KB, and many of the <code>default.px4board file</code> are already close to filling all the flash on their boards. To make room for the neural control module you can remove the include statements for other modules, such as FW, rover, VTOL and UUV.</p></div><h2 id="example-module-overview" tabindex="-1">Example Module Overview <a class="header-anchor" href="#example-module-overview" aria-label="Permalink to &quot;Example Module Overview&quot;">​</a></h2><p>The example module replaces the entire controller structure as well as the control allocator, as shown in the diagram below:</p><p><img src="`+i+'" alt="neural_control"></p><p>In the <a href="./../flight_stack/controller_diagrams.html">controller diagram</a> you can see the <a href="./../middleware/uorb.html">uORB message</a> flow. We hook into this flow by subscribing to messages at particular points, using our neural network to calculate outputs, and then publishing them into the next point in the flow. We also need to stop the module publishing the topic to be replaced, which is covered in <a href="./nn_module_utilities.html">Neural Network Module: System Integration</a></p><h3 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h3><p>The input can be changed to whatever you want. Set up the input you want to use during training and then provide the same input in PX4. In the Neural Control module the input is an array of 15 numbers, and consists of these values in this order:</p><ul><li>[3] Local position error. (goal position - current position)</li><li>[6] The first 2 rows of a 3 dimensional rotation matrix.</li><li>[3] Linear velocity</li><li>[3] Angular velocity</li></ul><p>All the input values are collected from uORB topics and transformed into the correct representation in the <code>PopulateInputTensor()</code> function. PX4 uses the NED frame representation, while the Aerial Gym Simulator, in which the NN was trained, uses the ENU representation. Therefore two rotation matrices are created in the function and all the inputs are transformed from the NED representation to the ENU one.</p><p><img src="'+n+'" alt="ENU-NED"></p><p>ENU and NED are just rotation representations, the translational difference is only there so both can be seen in the same figure.</p><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><p>The output consists of 4 values, the motor forces, one for each motor. These are transformed in the <code>RescaleActions()</code> function. This is done because PX4 expects normalized motor commands while the Aerial Gym Simulator uses physical values. So the output from the network needs to be normalized before they can be sent to the motors in PX4.</p><p>The commands are published to the <a href="./../msg_docs/ActuatorMotors.html">ActuatorMotors</a> topic. The publishing is handled in <code>PublishOutput(float* command_actions)</code> function.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the neural control mode is too aggressive or unresponsive the <a href="./../advanced_config/parameter_reference.html#MC_NN_THRST_COEF">MC_NN_THRST_COEF</a> parameter can be tuned. Decrease it for more thrust.</p></div><h2 id="training-your-own-network" tabindex="-1">Training your own Network <a class="header-anchor" href="#training-your-own-network" aria-label="Permalink to &quot;Training your own Network&quot;">​</a></h2><p>The network is currently trained for the <a href="./../frames_multicopter/holybro_x500v2_pixhawk6c.html">X500 V2</a>. But the controller is somewhat robust, so it could work directly on other platforms, but performing system identification and training a new network is recommended.</p><p>Since the Aerial Gym Simulator is open-source you can download it and train your own networks as long as you have access to an NVIDIA GPU. If you want to train a control network optimized for your platform you can follow the instructions in the <a href="https://ntnu-arl.github.io/aerial_gym_simulator/9_sim2real/" target="_blank" rel="noreferrer">Aerial Gym Documentation</a>.</p><p>You should do one system identification flight for this and get an approximate inertia matrix for your platform. On the <code>sys-id</code> flight you need ESC telemetry, you can read more about that in <a href="./../peripherals/dshot.html">DSHOT</a>.</p><p>Then do the following steps:</p><ul><li>Do a hover flight</li><li>Read of the logs what RPM is required for the drone to hover.</li><li>Use the weight of each motor, length of the motor arms, total weight of the platform with battery to calculate an approximate inertia matrix for the platform.</li><li>Insert these values into the Aerial Gym configuration and train your network.</li><li>Convert the network as explained in <a href="./tflm.html">TFLM</a>.</li></ul>',34))])}const _=s(u,[["render",c]]);export{v as __pageData,_ as default};
